import { createCipheriv, hkdfSync } from "node:crypto";
import { readFileSync } from "node:fs";

const frame = (value) => {
  const length = Buffer.alloc(2);
  length.writeUInt16BE(value.length);
  return Buffer.concat([length, value]);
};

const encrypt = (key, nonce, aad, plaintext) => {
  const cipher = createCipheriv("aes-256-gcm", key, nonce);
  cipher.setAAD(aad);
  return Buffer.concat([cipher.update(plaintext), cipher.final(), cipher.getAuthTag()]);
};

const sequence = (start, length) => Buffer.from(Array.from({ length }, (_, index) => start + index));
const text = (value) => Buffer.from(value, "utf8");
const masterKey = sequence(0x40, 32);
const dataKey = sequence(0x00, 32);
const payloadNonce = sequence(0xa0, 12);
const wrappingNonce = sequence(0xb0, 12);
const keyId = text("primary-2026");
const namespace = text("example-service");
const purpose = text("private-record");
const owner = text("account-42");
const resource = text("record-17");
const schema = text("record-bytes-v1");
const plaintext = text("Portable deterministic fixture\n");
const context = Buffer.concat([
  Buffer.from([1, 1]),
  frame(namespace),
  frame(purpose),
  frame(owner),
  frame(resource),
  frame(schema),
]);
const tenantContext = Buffer.concat([
  Buffer.from([1, 2]),
  frame(namespace),
  frame(text("external-token")),
  frame(owner),
  frame(text("token-v1")),
]);
const descriptor = Buffer.concat([Buffer.from([1, 12]), payloadNonce]);
const hkdfInfo = Buffer.concat([
  text("ATRK"),
  Buffer.from([1, 3]),
  frame(namespace),
  frame(purpose),
]);
const wrappingKey = Buffer.from(
  hkdfSync(
    "sha256",
    masterKey,
    text("at-rest:envelope:v1:wrapping-key:salt"),
    hkdfInfo,
    32,
  ),
);
const payloadAad = Buffer.concat([text("ATRA"), Buffer.from([1, 1]), frame(context)]);
const wrappingAad = Buffer.concat([
  text("ATRA"),
  Buffer.from([2, 1]),
  frame(keyId),
  frame(payloadNonce),
  frame(context),
]);
const encryptedDataKey = encrypt(wrappingKey, wrappingNonce, wrappingAad, dataKey);
const body = encrypt(dataKey, payloadNonce, payloadAad, plaintext);
const wrappedKey = Buffer.concat([
  Buffer.from([keyId.length]),
  keyId,
  Buffer.from([wrappingNonce.length]),
  wrappingNonce,
  frame(encryptedDataKey),
]);
const envelope = Buffer.concat([text("ATRE"), frame(descriptor), frame(wrappedKey)]);
const bodyLength = Buffer.alloc(4);
bodyLength.writeUInt32BE(body.length);
const sealedPayload = Buffer.concat([text("ATRS"), frame(envelope), bodyLength, body]);

const values = Object.entries({
  master_key: masterKey,
  data_key: dataKey,
  payload_nonce: payloadNonce,
  wrapping_nonce: wrappingNonce,
  key_id: keyId,
  plaintext,
  context,
  tenant_context: tenantContext,
  descriptor,
  wrapped_key: wrappedKey,
  envelope,
  body,
  sealed_payload: sealedPayload,
});
const header = "# Generated by generate-envelope-v1.mjs using only Node's standard crypto library.";
const generated = `${header}\n${values
  .map(([name, value]) => `${name}=${value.toString("hex")}`)
  .join("\n")}\n`;

if (process.argv.length === 2) {
  process.stdout.write(generated);
} else if (process.argv.length === 3 && process.argv[2] === "--check") {
  const fixture = readFileSync(new URL("./envelope-v1.txt", import.meta.url), "utf8");
  if (fixture !== generated) {
    throw new Error("envelope-v1.txt does not match the independent generator");
  }
  process.stdout.write("envelope-v1.txt matches the independent generator\n");
} else {
  throw new Error("usage: node generate-envelope-v1.mjs [--check]");
}
